  rd_l2_kpi_rev_up: { en: "▲ 18% vs last month", fil: "▲ 18% vs nakaraang buwan", zh: "▲ 18% 较上月", "zh-TW": "▲ 18% 較上月", vi: "▲ 18% so với tháng trước", th: "▲ 18% เทียบเดือนก่อน", id: "▲ 18% vs bulan lalu", bg: "▲ 18% спрямо миналия месец" },
