  rd_win_save_failed: { en: "Couldn't save the session length — reverted. Check your connection and try again.", fil: "Hindi na-save ang session length — ibinalik. Suriin ang koneksyon at subukan muli.", zh: "无法保存场次天数——已还原。请检查网络后重试。", "zh-TW": "無法儲存場次天數——已還原。請檢查網路後重試。", vi: "Không lưu được độ dài phiên — đã hoàn tác. Kiểm tra kết nối và thử lại.", th: "บันทึกจำนวนวันของเซสชันไม่สำเร็จ — คืนค่าแล้ว ตรวจสอบการเชื่อมต่อแล้วลองใหม่", id: "Tidak bisa menyimpan panjang sesi — dikembalikan. Periksa koneksi dan coba lagi.", bg: "Продължителността на сесията не се запази — върната е. Провери връзката и опитай пак." },
  rd_raffle_save_failed: { en: "Couldn't save the Games switch — check your connection and try again.", fil: "Hindi na-save ang Games switch — suriin ang koneksyon at subukan muli.", zh: "无法保存 Games 开关——请检查网络后重试。", "zh-TW": "無法儲存 Games 開關——請檢查網路後重試。", vi: "Không lưu được công tắc Games — kiểm tra kết nối và thử lại.", th: "บันทึกสวิตช์ Games ไม่สำเร็จ — ตรวจสอบการเชื่อมต่อแล้วลองใหม่", id: "Tidak bisa menyimpan sakelar Games — periksa koneksi dan coba lagi.", bg: "Превключвателят Игри не се запази — провери връзката и опитай пак." },
  rd_prd_sync_failed: { en: "Saved on this phone only — it didn't go online. Check your connection.", fil: "Sa phone na 'to lang na-save — hindi pa naka-online. I-check ang internet.", zh: "只保存在这部手机上——还没上传。请检查网络。", "zh-TW": "只儲存在這支手機上——還沒上傳。請檢查網路。", vi: "Chỉ lưu trên điện thoại này — chưa lên mạng. Hãy kiểm tra kết nối.", th: "บันทึกไว้ในโทรศัพท์นี้เท่านั้น — ยังไม่ขึ้นออนไลน์ ตรวจสอบการเชื่อมต่อ", id: "Hanya tersimpan di HP ini — belum tersimpan online. Periksa koneksi Anda.", bg: "Запазено само на този телефон — не е качено онлайн. Провери връзката си." },
  rd_prd_delete_failed: { en: "Delete failed — the product was restored. Check your connection and try again.", fil: "Nabigo ang pag-delete — ibinalik ang produkto. Suriin ang koneksyon at subukan muli.", zh: "删除失败——商品已恢复。请检查网络后重试。", "zh-TW": "刪除失敗——商品已恢復。請檢查網路後重試。", vi: "Xóa thất bại — sản phẩm đã được khôi phục. Kiểm tra kết nối và thử lại.", th: "ลบไม่สำเร็จ — สินค้าถูกกู้คืนแล้ว ตรวจสอบการเชื่อมต่อแล้วลองใหม่", id: "Gagal menghapus — produk dikembalikan. Periksa koneksi dan coba lagi.", bg: "Изтриването не успя — продуктът е възстановен. Провери връзката и опитай пак." },
  rd_shp_exported: { en: "Exported", fil: "Na-export", zh: "已导出", "zh-TW": "已匯出", vi: "Đã xuất", th: "ส่งออกแล้ว", id: "Diekspor", bg: "Експортирани" },
  rd_shp_export_ok: { en: "{n} exported — {file} downloaded. Upload it at myship.7-11.com.tw.", fil: "{n} na-export — na-download ang {file}. I-upload ito sa myship.7-11.com.tw.", zh: "已导出 {n} 笔——已下载 {file}。请到 myship.7-11.com.tw 上传。", "zh-TW": "已匯出 {n} 筆——已下載 {file}。請到 myship.7-11.com.tw 上傳。", vi: "Đã xuất {n} — đã tải {file}. Tải lên tại myship.7-11.com.tw.", th: "ส่งออก {n} รายการ — ดาวน์โหลด {file} แล้ว อัปโหลดที่ myship.7-11.com.tw", id: "{n} diekspor — {file} terunduh. Unggah di myship.7-11.com.tw.", bg: "{n} експортирани — {file} е свален. Качи го на myship.7-11.com.tw." },
  rd_shp_export_failed: { en: "Couldn't export. Please try again.", fil: "Hindi na-export. Subukan ulit.", zh: "导出失败，请重试。", "zh-TW": "匯出失敗，請再試一次。", vi: "Không xuất được. Vui lòng thử lại.", th: "ส่งออกไม่ได้ โปรดลองอีกครั้ง", id: "Gagal mengekspor. Coba lagi.", bg: "Експортът не успя. Опитай пак." },
  rd_shp_dl_failed: { en: "Your entries are marked exported, but the file didn't download. Try again on a computer.", fil: "Na-mark nang exported, pero hindi na-download ang file. Subukan ulit sa computer.", zh: "记录已标记为已导出，但文件没有下载。请在电脑上重试。", "zh-TW": "記錄已標記為已匯出，但檔案沒有下載。請在電腦上再試一次。", vi: "Các mục đã được đánh dấu đã xuất, nhưng tệp chưa tải xuống. Hãy thử lại trên máy tính.", th: "รายการถูกทำเครื่องหมายว่าส่งออกแล้ว แต่ไฟล์ไม่ได้ดาวน์โหลด ลองอีกครั้งบนคอมพิวเตอร์", id: "Entri sudah ditandai diekspor, tapi file tidak terunduh. Coba lagi di komputer.", bg: "Записите са отбелязани като експортирани, но файлът не се изтегли. Опитай пак от компютър." },
  rd_shp_export_browser: { en: "Exporting the 7-11 file needs a browser — open sellerflowlive.com on your computer or phone browser. Everything you encoded here is already saved.", fil: "Kailangan ng browser para i-export ang 7-11 file — buksan ang sellerflowlive.com sa computer o phone browser mo. Naka-save na ang lahat ng na-encode mo rito.", zh: "导出 7-11 文件需要浏览器——请在电脑或手机浏览器打开 sellerflowlive.com。你在这里输入的内容都已保存。", "zh-TW": "匯出 7-11 檔案需要瀏覽器——請在電腦或手機瀏覽器開啟 sellerflowlive.com。你在這裡輸入的內容都已儲存。", vi: "Xuất tệp 7-11 cần trình duyệt — mở sellerflowlive.com trên máy tính hoặc trình duyệt điện thoại. Mọi thứ bạn nhập ở đây đã được lưu.", th: "การส่งออกไฟล์ 7-11 ต้องใช้เบราว์เซอร์ — เปิด sellerflowlive.com บนคอมพิวเตอร์หรือเบราว์เซอร์มือถือ ทุกอย่างที่คุณกรอกไว้ที่นี่บันทึกแล้ว", id: "Ekspor file 7-11 butuh browser — buka sellerflowlive.com di komputer atau browser HP. Semua yang Anda isi di sini sudah tersimpan.", bg: "За експорт на 7-11 файла ти трябва браузър — отвори sellerflowlive.com на компютъра или в браузъра на телефона. Всичко въведено тук вече е запазено." },
  rd_shp_none_encoded: { en: "Encode buyers above to enable export.", fil: "I-encode muna ang mga buyer sa itaas para ma-enable ang export.", zh: "请先填写上方买家资料以启用导出。", "zh-TW": "請先填寫上方買家資料以啟用匯出。", vi: "Nhập thông tin người mua ở trên để bật xuất.", th: "กรอกข้อมูลผู้ซื้อด้านบนเพื่อเปิดใช้การส่งออก", id: "Isi data pembeli di atas untuk mengaktifkan ekspor.", bg: "Въведи купувачите по-горе, за да отключиш експорта." },
