  rd_inv_desc: { en: "Share SellerFlowLive with other live sellers.", fil: "Ibahagi ang SellerFlowLive sa ibang live seller.", zh: "把 SellerFlowLive 分享给其他直播卖家。", "zh-TW": "把 SellerFlowLive 分享給其他直播賣家。", vi: "Chia sẻ SellerFlowLive với những người bán live khác.", th: "แชร์ SellerFlowLive ให้ผู้ขายไลฟ์คนอื่น", id: "Bagikan SellerFlowLive ke penjual live lainnya.", bg: "Сподели SellerFlowLive с други лайв продавачи." },
  rd_inv_share: { en: "Try SellerFlowLive — it turns your live comments into printed order stickers automatically, for TikTok & Facebook live.", fil: "Subukan ang SellerFlowLive — awtomatiko nitong ginagawang naka-print na order sticker ang mga live comment mo, para sa TikTok at Facebook live.", zh: "试试 SellerFlowLive——它能把你的直播评论自动变成打印好的订单贴纸，支持 TikTok 和 Facebook 直播。", "zh-TW": "試試 SellerFlowLive——它能把你的直播留言自動變成列印好的訂單貼紙，支援 TikTok 與 Facebook 直播。", vi: "Thử SellerFlowLive — nó tự động biến bình luận live của bạn thành sticker đơn hàng đã in, cho live TikTok & Facebook.", th: "ลองใช้ SellerFlowLive — เปลี่ยนคอมเมนต์ไลฟ์ของคุณให้เป็นสติกเกอร์ออเดอร์ที่พิมพ์แล้วโดยอัตโนมัติ สำหรับไลฟ์ TikTok และ Facebook", id: "Coba SellerFlowLive — otomatis mengubah komentar live kamu jadi stiker pesanan tercetak, untuk live TikTok & Facebook.", bg: "Пробвай SellerFlowLive — превръща лайв коментарите ти автоматично в отпечатани стикери за поръчки, за TikTok и Facebook live." },
  rd_inv_copied: { en: "Link copied", fil: "Nakopya ang link", zh: "链接已复制", "zh-TW": "連結已複製", vi: "Đã sao chép liên kết", th: "คัดลอกลิงก์แล้ว", id: "Tautan disalin", bg: "Линкът е копиран" },
  rd_inv_copy_failed: { en: "Couldn't copy — copy the link manually", fil: "Hindi nakopya — kopyahin nang manu-mano ang link", zh: "复制失败——请手动复制链接", "zh-TW": "複製失敗——請手動複製連結", vi: "Không sao chép được — hãy sao chép liên kết thủ công", th: "คัดลอกไม่สำเร็จ — คัดลอกลิงก์ด้วยตนเอง", id: "Gagal menyalin — salin tautan secara manual", bg: "Не се копира — копирай линка ръчно" },
