  rd_upd_msg_ble: { en: "A new version is available.", fil: "May bagong bersyon na available.", zh: "有新版本可供更新。", "zh-TW": "有新版本可供更新。", vi: "Đã có phiên bản mới.", th: "มีเวอร์ชันใหม่ให้อัปเดตแล้ว", id: "Versi baru tersedia.", bg: "Налична е нова версия." },
  rd_upd_msg_generic: { en: "A new version is available — update for the latest features and fixes.", fil: "May bagong bersyon na — mag-update para sa pinakabagong features at fixes.", zh: "有新版本可用——更新以获取最新功能和修复。", "zh-TW": "有新版本可用——更新以取得最新功能與修正。", vi: "Đã có phiên bản mới — cập nhật để có tính năng và bản sửa lỗi mới nhất.", th: "มีเวอร์ชันใหม่แล้ว — อัปเดตเพื่อรับฟีเจอร์และการแก้ไขล่าสุด", id: "Versi baru tersedia — perbarui untuk fitur dan perbaikan terbaru.", bg: "Налична е нова версия — обнови за най-новите функции и поправки." },
  rd_upd_action: { en: "Update now", fil: "Mag-update na", zh: "立即更新", "zh-TW": "立即更新", vi: "Cập nhật ngay", th: "อัปเดตเลย", id: "Perbarui sekarang", bg: "Обнови сега" },
