  rd_wg_title: { en: "Set up your WiFi printer", fil: "I-set up ang WiFi printer mo", zh: "设置你的 WiFi 打印机", "zh-TW": "設定你的 WiFi 印表機", vi: "Thiết lập máy in WiFi của bạn", th: "ตั้งค่าเครื่องพิมพ์ WiFi ของคุณ", id: "Siapkan printer WiFi Anda", bg: "Настрой своя WiFi принтер" },
  rd_wg_1: { en: "Connect your receipt printer to the same WiFi network as this phone.", fil: "Ikonekta ang receipt printer sa parehong WiFi ng telepono mo.", zh: "将小票打印机连接到与此手机相同的 WiFi 网络。", "zh-TW": "將出單印表機連上與這支手機相同的 WiFi 網路。", vi: "Kết nối máy in hóa đơn vào cùng mạng WiFi với điện thoại này.", th: "เชื่อมต่อเครื่องพิมพ์สลิปเข้ากับ WiFi เดียวกับโทรศัพท์นี้", id: "Hubungkan printer struk ke jaringan WiFi yang sama dengan ponsel ini.", bg: "Свържи принтера за бележки към същата WiFi мрежа като този телефон." },
  rd_wg_2: { en: "Print the printer's test page — it shows the printer's number (like 192.168.x.x).", fil: "I-print ang test page ng printer — nandoon ang number nito.", zh: "打印打印机的测试页——上面会显示打印机的号码（例如 192.168.x.x）。", "zh-TW": "列印印表機的測試頁——上面會顯示印表機的號碼（例如 192.168.x.x）。", vi: "In trang thử của máy in — trên đó có số của máy in (vd. 192.168.x.x).", th: "พิมพ์หน้าทดสอบของเครื่องพิมพ์ — จะแสดงหมายเลขของเครื่องพิมพ์ (เช่น 192.168.x.x)", id: "Cetak halaman tes printer — di situ ada nomor printer (mis. 192.168.x.x).", bg: "Отпечатай тестова страница от принтера — на нея е номерът му (напр. 192.168.x.x)." },
  rd_wg_3: { en: "Enter that number on the next screen.", fil: "Ilagay ang number na iyon sa susunod na screen.", zh: "在下一个画面输入该号码。", "zh-TW": "在下一個畫面輸入該號碼。", vi: "Nhập số đó ở màn hình tiếp theo.", th: "ใส่หมายเลขนั้นในหน้าถัดไป", id: "Masukkan nomor itu di layar berikutnya.", bg: "Въведи този номер на следващия екран." },
  rd_wg_4: { en: "Tap Test Connection, then Test Print to confirm.", fil: "I-tap ang Test Connection, tapos Test Print para kumpirmahin.", zh: "点击「测试连接」，然后「测试打印」确认。", "zh-TW": "點擊「測試連線」，再「測試列印」確認。", vi: "Chạm Kiểm tra kết nối, rồi In thử để xác nhận.", th: "แตะ ทดสอบการเชื่อมต่อ แล้ว ทดสอบพิมพ์ เพื่อยืนยัน", id: "Ketuk Tes Koneksi, lalu Tes Cetak untuk memastikan.", bg: "Докосни Тест на връзката, после Тестов печат за потвърждение." },
  rd_bg_title: { en: "Set up your Bluetooth printer", fil: "I-set up ang Bluetooth printer mo", zh: "设置你的蓝牙打印机", "zh-TW": "設定你的藍牙印表機", vi: "Thiết lập máy in Bluetooth của bạn", th: "ตั้งค่าเครื่องพิมพ์ Bluetooth ของคุณ", id: "Siapkan printer Bluetooth Anda", bg: "Настрой своя Bluetooth принтер" },
  rd_bg_1: { en: "Turn on your sticker printer and keep it close.", fil: "Buksan ang sticker printer mo at ilapit.", zh: "打开你的贴纸打印机并放在附近。", "zh-TW": "開啟你的貼紙印表機並放在附近。", vi: "Bật máy in sticker và để gần bên.", th: "เปิดเครื่องพิมพ์สติกเกอร์และวางไว้ใกล้ ๆ", id: "Nyalakan printer stiker Anda dan dekatkan.", bg: "Включи стикер принтера и го дръж наблизо." },
  rd_bg_2: { en: "Make sure it isn't connected to another app or phone.", fil: "Siguraduhing hindi ito nakakonekta sa ibang app o telepono.", zh: "确保它没有连接到其他应用或手机。", "zh-TW": "確認它沒有連到其他 App 或手機。", vi: "Đảm bảo nó không kết nối với ứng dụng hay điện thoại khác.", th: "ตรวจสอบว่าไม่ได้เชื่อมต่อกับแอปหรือโทรศัพท์เครื่องอื่น", id: "Pastikan tidak terhubung ke aplikasi atau ponsel lain.", bg: "Увери се, че не е свързан с друго приложение или телефон." },
  rd_bg_3: { en: "Tap Scan, then pick your printer from the list.", fil: "I-tap ang Scan, tapos piliin ang printer mo sa listahan.", zh: "点击「扫描」，然后从列表中选择你的打印机。", "zh-TW": "點擊「掃描」，再從清單中選擇你的印表機。", vi: "Chạm Quét, rồi chọn máy in của bạn từ danh sách.", th: "แตะ สแกน แล้วเลือกเครื่องพิมพ์ของคุณจากรายการ", id: "Ketuk Pindai, lalu pilih printer Anda dari daftar.", bg: "Натисни Сканирай и избери принтера си от списъка." },
  rd_bg_4: { en: "Tap Test Print to confirm it works.", fil: "I-tap ang Test Print para kumpirmahin na gumagana.", zh: "点击「测试打印」确认可以使用。", "zh-TW": "點擊「測試列印」確認可以運作。", vi: "Chạm In thử để xác nhận nó hoạt động.", th: "แตะ ทดสอบพิมพ์ เพื่อยืนยันว่าใช้งานได้", id: "Ketuk Tes Cetak untuk memastikan berfungsi.", bg: "Натисни Тестов печат, за да провериш, че работи." },
