  rd_adm_ctrl_parcelsw: { en: "Parcel access", fil: "Parcel access", zh: "包裹权限", "zh-TW": "包裹權限", vi: "Quyền Parcel", th: "สิทธิ์ Parcel", id: "Akses Parcel", bg: "Достъп до пратки" },
  rd_adm_pt_parcelsw: { en: "Parcel Scan — seller access", fil: "Parcel Scan — access ng seller", zh: "Parcel Scan — 卖家权限", "zh-TW": "Parcel Scan — 賣家權限", vi: "Parcel Scan — quyền người bán", th: "Parcel Scan — สิทธิ์ผู้ขาย", id: "Parcel Scan — akses penjual", bg: "Parcel Scan — достъп за продавачи" },
  rd_adm_psw_hint: { en: "When ON, paying active sellers can use manual parcel encode. When OFF, Parcel Scan is admin-only. Admins always have access, either way.", fil: "Kapag ON, magagamit ng paying active sellers ang manual parcel encode. Kapag OFF, admin-only ang Parcel Scan. May access lagi ang admin, alinman.", zh: "开启时，付费且有效的卖家可使用手动包裹录入；关闭时，Parcel Scan 仅限管理员。无论如何管理员始终有权限。", "zh-TW": "開啟時，付費且有效的賣家可使用手動包裹輸入；關閉時，Parcel Scan 僅限管理員。無論如何管理員始終有權限。", vi: "Khi BẬT, người bán trả phí đang hoạt động dùng được nhập kiện thủ công. Khi TẮT, Parcel Scan chỉ dành cho admin. Admin luôn có quyền.", th: "เมื่อเปิด ผู้ขายที่จ่ายเงินและใช้งานอยู่จะใช้การกรอกพัสดุแบบแมนนวลได้ เมื่อปิด Parcel Scan จะเฉพาะแอดมิน แอดมินมีสิทธิ์เสมอ", id: "Saat ON, penjual berbayar yang aktif bisa memakai input parsel manual. Saat OFF, Parcel Scan hanya admin. Admin selalu punya akses.", bg: "Когато е ВКЛ., плащащите активни продавачи могат да въвеждат пратки ръчно. Когато е ИЗКЛ., Parcel Scan е само за администратори. Администраторите винаги имат достъп." },
  rd_adm_psw_current: { en: "Current", fil: "Kasalukuyan", zh: "当前", "zh-TW": "目前", vi: "Hiện tại", th: "ปัจจุบัน", id: "Saat ini", bg: "Текущо" },
  rd_adm_psw_on: { en: "ON — sellers can use manual encode", fil: "ON — magagamit ng sellers ang manual encode", zh: "开启——卖家可使用手动录入", "zh-TW": "開啟——賣家可使用手動輸入", vi: "BẬT — người bán dùng được nhập thủ công", th: "เปิด — ผู้ขายใช้การกรอกแมนนวลได้", id: "ON — penjual bisa input manual", bg: "ВКЛ. — продавачите могат да въвеждат ръчно" },
