  rd_shp_remove_confirm: { en: "Remove this Shopee shop? You'll need to authorize it again to reconnect.", fil: "Alisin ang Shopee shop na ito? Kailangan mo itong i-authorize ulit para makakonekta muli.", zh: "移除此 Shopee 店铺？重新连接需再次授权。", "zh-TW": "移除此 Shopee 賣場？重新連線需再次授權。", vi: "Xoá cửa hàng Shopee này? Bạn sẽ cần uỷ quyền lại để kết nối.", th: "ลบร้าน Shopee นี้? คุณต้องอนุญาตใหม่เพื่อเชื่อมต่ออีกครั้ง", id: "Hapus toko Shopee ini? Anda perlu mengotorisasi ulang untuk menyambung kembali.", bg: "Да премахна ли този Shopee магазин? Ще трябва да го оторизираш отново, за да се свържеш." },
  rd_shp_cap: { en: "You've reached your plan's account limit ({max}). Remove a shop or contact support to add more.", fil: "Naabot mo na ang limitasyon ng iyong plan ({max}). Mag-alis ng shop o kontakin ang support para makadagdag.", zh: "已达到你套餐的账号上限（{max}）。请移除店铺或联系客服以增加。", "zh-TW": "已達到你方案的帳號上限（{max}）。請移除賣場或聯絡客服以增加。", vi: "Bạn đã đạt giới hạn tài khoản của gói ({max}). Xoá bớt cửa hàng hoặc liên hệ hỗ trợ để thêm.", th: "คุณถึงขีดจำกัดบัญชีของแพ็กเกจแล้ว ({max}) ลบร้านหรือติดต่อฝ่ายสนับสนุนเพื่อเพิ่ม", id: "Anda mencapai batas akun paket Anda ({max}). Hapus toko atau hubungi dukungan untuk menambah.", bg: "Достигна лимита акаунти на плана си ({max}). Премахни магазин или се свържи с поддръжката за още." },
  rd_shp_connect: { en: "Connect", fil: "Kumonekta", zh: "连接", "zh-TW": "連線", vi: "Kết nối", th: "เชื่อมต่อ", id: "Sambungkan", bg: "Свържи" },
  rd_shp_connecting: { en: "Connecting…", fil: "Kumokonekta…", zh: "连接中…", "zh-TW": "連線中…", vi: "Đang kết nối…", th: "กำลังเชื่อมต่อ…", id: "Menyambungkan…", bg: "Свързване…" },
  rd_shp_disconnect: { en: "Disconnect", fil: "Idiskonekta", zh: "断开", "zh-TW": "中斷連線", vi: "Ngắt kết nối", th: "ตัดการเชื่อมต่อ", id: "Putuskan", bg: "Прекъсни" },
  rd_shp_connect_title: { en: "Connect Shopee", fil: "Ikonekta ang Shopee", zh: "连接 Shopee", "zh-TW": "連線 Shopee", vi: "Kết nối Shopee", th: "เชื่อมต่อ Shopee", id: "Sambungkan Shopee", bg: "Свържи Shopee" },
  rd_shp_pick_shop: { en: "Choose a shop", fil: "Pumili ng shop", zh: "选择店铺", "zh-TW": "選擇賣場", vi: "Chọn cửa hàng", th: "เลือกร้าน", id: "Pilih toko", bg: "Избери магазин" },
  rd_shp_session_label: { en: "Your Shopee Live code", fil: "Live code mo sa Shopee", zh: "你的 Shopee 直播代码", "zh-TW": "你的 Shopee 直播代碼", vi: "Mã Shopee Live của bạn", th: "รหัส Shopee Live ของคุณ", id: "Kode Shopee Live Anda", bg: "Твоят Shopee Live код" },
  rd_shp_session_ph: { en: "Paste your Shopee Live code", fil: "I-paste ang Live code mo sa Shopee", zh: "粘贴你的 Shopee 直播代码", "zh-TW": "貼上你的 Shopee 直播代碼", vi: "Dán mã Shopee Live của bạn", th: "วางรหัส Shopee Live ของคุณ", id: "Tempel kode Shopee Live Anda", bg: "Постави своя Shopee Live код" },
  rd_shp_session_help: { en: "Open your Shopee live page, copy your Live code and paste it here.", fil: "Buksan ang Shopee live page mo, kopyahin ang Live code at i-paste dito.", zh: "打开你的 Shopee 直播页面，复制直播代码并粘贴到这里。", "zh-TW": "打開你的 Shopee 直播頁面，複製直播代碼並貼到這裡。", vi: "Mở trang live Shopee của bạn, sao chép mã Live và dán vào đây.", th: "เปิดหน้าไลฟ์ Shopee ของคุณ คัดลอกรหัสไลฟ์แล้ววางที่นี่", id: "Buka halaman live Shopee Anda, salin kode Live lalu tempel di sini.", bg: "Отвори страницата си за лайв в Shopee, копирай Live кода и го постави тук." },
  rd_shp_not_live: { en: "Couldn't start — check your Live code and that your Shopee Live is running.", fil: "Hindi nagsimula — i-check ang Live code mo at kung naka-live ka sa Shopee.", zh: "无法开始——请检查直播代码，并确认你的 Shopee 直播正在进行。", "zh-TW": "無法開始——請檢查直播代碼，並確認你的 Shopee 直播正在進行。", vi: "Không bắt đầu được — kiểm tra mã Live và đảm bảo Shopee Live đang chạy.", th: "เริ่มไม่ได้ — ตรวจสอบรหัสไลฟ์ และดูว่า Shopee Live ของคุณกำลังไลฟ์อยู่", id: "Tidak bisa mulai — periksa kode Live dan pastikan Shopee Live Anda sedang berjalan.", bg: "Не стартира — провери Live кода и дали Shopee Live е включен." },
  rd_shp_connect_failed: { en: "Couldn't connect your Shopee shop. Please try again.", fil: "Hindi ma-connect ang Shopee shop mo. Subukan ulit.", zh: "无法连接你的 Shopee 店铺，请重试。", "zh-TW": "無法連接你的 Shopee 商店，請再試一次。", vi: "Không kết nối được shop Shopee của bạn. Vui lòng thử lại.", th: "เชื่อมต่อร้าน Shopee ของคุณไม่ได้ โปรดลองอีกครั้ง", id: "Tidak bisa menghubungkan toko Shopee Anda. Coba lagi.", bg: "Не успяхме да свържем твоя Shopee магазин. Опитай пак." },
  rd_shp_connected_toast: { en: "Shopee connected!", fil: "Konektado na sa Shopee!", zh: "Shopee 已连接！", "zh-TW": "Shopee 已連線！", vi: "Đã kết nối Shopee!", th: "เชื่อมต่อ Shopee แล้ว!", id: "Shopee tersambung!", bg: "Shopee е свързан!" },
  rd_shp_authorized_toast: { en: "Shopee shop authorized!", fil: "Na-authorize ang Shopee shop!", zh: "Shopee 店铺已授权！", "zh-TW": "Shopee 賣場已授權！", vi: "Đã uỷ quyền cửa hàng Shopee!", th: "อนุญาตร้าน Shopee แล้ว!", id: "Toko Shopee diotorisasi!", bg: "Shopee магазинът е оторизиран!" },
  // ── FACEBOOK LIVE (F-P3) — pages management + connect. Owner-gated (FB_PREVIEW_EMAILS
