  rd_ig_authorize: { en: "Authorize Instagram", fil: "I-authorize ang Instagram", zh: "授权 Instagram", "zh-TW": "授權 Instagram", vi: "Uỷ quyền Instagram", th: "อนุญาต Instagram", id: "Otorisasi Instagram", bg: "Оторизирай Instagram" },
  rd_ig_authorize_help: { en: "You'll log in with Facebook and choose the Page your Instagram account is linked to. Come back here after — your account appears above.", fil: "Magla-log in ka gamit ang Facebook at pipili ng Page na naka-link sa Instagram account mo. Bumalik dito pagkatapos — lalabas ang account mo sa itaas.", zh: "你将用 Facebook 登录并选择与 Instagram 账号关联的主页。完成后返回这里——你的账号会显示在上方。", "zh-TW": "你將用 Facebook 登入並選擇與 Instagram 帳號連結的粉專。完成後返回這裡——你的帳號會顯示在上方。", vi: "Bạn sẽ đăng nhập bằng Facebook và chọn Trang liên kết với tài khoản Instagram. Quay lại đây sau — tài khoản sẽ hiện ở trên.", th: "คุณจะเข้าสู่ระบบด้วย Facebook และเลือกเพจที่เชื่อมกับบัญชี Instagram กลับมาที่นี่หลังจากนั้น — บัญชีของคุณจะปรากฏด้านบน", id: "Anda akan masuk dengan Facebook dan memilih Halaman yang terhubung ke akun Instagram. Kembali ke sini setelahnya — akun Anda muncul di atas.", bg: "Ще влезеш с Facebook и ще избереш страницата, свързана с Instagram акаунта ти. Върни се тук след това — акаунтът ще се появи по-горе." },
  rd_ig_remove_confirm: { en: "Remove this Instagram account?", fil: "Alisin ang Instagram account na ito?", zh: "移除这个 Instagram 账号？", "zh-TW": "移除這個 Instagram 帳號？", vi: "Xoá tài khoản Instagram này?", th: "ลบบัญชี Instagram นี้ใช่ไหม?", id: "Hapus akun Instagram ini?", bg: "Да премахна ли този Instagram акаунт?" },
  rd_ig_removed_toast: { en: "Instagram account removed.", fil: "Naalis ang Instagram account.", zh: "已移除 Instagram 账号。", "zh-TW": "已移除 Instagram 帳號。", vi: "Đã xoá tài khoản Instagram.", th: "ลบบัญชี Instagram แล้ว", id: "Akun Instagram dihapus.", bg: "Instagram акаунтът е премахнат." },
  rd_ig_remove_err: { en: "Couldn't remove the account. Please try again.", fil: "Hindi naalis ang account. Pakisubukan ulit.", zh: "无法移除账号，请重试。", "zh-TW": "無法移除帳號，請重試。", vi: "Không xoá được tài khoản. Vui lòng thử lại.", th: "ลบบัญชีไม่สำเร็จ กรุณาลองใหม่", id: "Gagal menghapus akun. Silakan coba lagi.", bg: "Акаунтът не се премахна. Опитай пак." },
