  rd_ig_cap: { en: "Account limit reached: up to {max} accounts.", fil: "Naabot ang limit: hanggang {max} account.", zh: "已达账号上限：最多 {max} 个账号。", "zh-TW": "已達帳號上限：最多 {max} 個帳號。", vi: "Đã đạt giới hạn: tối đa {max} tài khoản.", th: "ถึงขีดจำกัดแล้ว: สูงสุด {max} บัญชี", id: "Batas akun tercapai: maksimal {max} akun.", bg: "Достигнат лимит: до {max} акаунта." },
  rd_shp_auth_error_toast: { en: "Shopee authorization failed. Please try again.", fil: "Nabigo ang Shopee authorization. Pakisubukan ulit.", zh: "Shopee 授权失败，请重试。", "zh-TW": "Shopee 授權失敗，請重試。", vi: "Uỷ quyền Shopee thất bại. Vui lòng thử lại.", th: "การอนุญาต Shopee ล้มเหลว กรุณาลองใหม่", id: "Otorisasi Shopee gagal. Silakan coba lagi.", bg: "Shopee оторизацията не успя. Опитай пак." },
