  rd_pt_sync_hint: { en: "Upload the 匯出報表 to show buyer usernames and pickup status.", fil: "I-upload ang 匯出報表 para makita ang buyer usernames at pickup status.", zh: "上传匯出報表以显示买家帐号和取件状态。", "zh-TW": "上傳匯出報表以顯示買家帳號與取件狀態。", vi: "Tải lên 匯出報表 để hiển thị username người mua và trạng thái lấy hàng.", th: "อัปโหลด 匯出報表 เพื่อแสดง username ผู้ซื้อและสถานะรับพัสดุ", id: "Unggah 匯出報表 untuk menampilkan username pembeli dan status ambil.", bg: "Качи 匯出報表, за да се покажат имената на купувачите и статусът на получаване." },
  rd_pt_sync_how: { en: "How to sync?", fil: "Paano mag-sync?", zh: "如何同步？", "zh-TW": "如何同步？", vi: "Cách đồng bộ?", th: "ซิงค์อย่างไร?", id: "Cara sinkron?", bg: "Как се синхронизира?" },
  rd_pt_sync_how_hide: { en: "Hide steps", fil: "Itago ang mga hakbang", zh: "隐藏步骤", "zh-TW": "隱藏步驟", vi: "Ẩn các bước", th: "ซ่อนขั้นตอน", id: "Sembunyikan langkah", bg: "Скрий стъпките" },
  rd_pt_sync_s1: { en: "In Parcel Scan, enter the buyer's @username → export → upload to 賣貨便 as usual.", fil: "Sa Parcel Scan, ilagay ang @username ng buyer → i-export → i-upload sa 賣貨便 gaya ng dati.", zh: "在包裹扫描中输入买家 @帐号 → 导出 → 照常上传到賣貨便。", "zh-TW": "在包裹掃描中輸入買家 @帳號 → 匯出 → 照常上傳到賣貨便。", vi: "Trong Parcel Scan, nhập @username người mua → xuất → tải lên 賣貨便 như thường lệ.", th: "ใน Parcel Scan ใส่ @username ผู้ซื้อ → ส่งออก → อัปโหลดไป 賣貨便 ตามปกติ", id: "Di Parcel Scan, isi @username pembeli → ekspor → unggah ke 賣貨便 seperti biasa.", bg: "В Parcel Scan въведи @username на купувача → експортирай → качи в 賣貨便 както обикновено." },
  rd_pt_sync_s2: { en: "賣家訂單 → 待出貨 → 匯出報表 (download it in a normal browser, not inside the app).", fil: "賣家訂單 → 待出貨 → 匯出報表 (i-download sa normal na browser, hindi sa loob ng app).", zh: "賣家訂單 → 待出貨 → 匯出報表（在一般浏览器下载，不要在 App 内）。", "zh-TW": "賣家訂單 → 待出貨 → 匯出報表（在一般瀏覽器下載，不要在 App 內）。", vi: "賣家訂單 → 待出貨 → 匯出報表 (tải bằng trình duyệt thường, không trong app).", th: "賣家訂單 → 待出貨 → 匯出報表 (ดาวน์โหลดในเบราว์เซอร์ปกติ ไม่ใช่ในแอป)", id: "賣家訂單 → 待出貨 → 匯出報表 (unduh di browser biasa, bukan di dalam app).", bg: "賣家訂單 → 待出貨 → 匯出報表 (свали го в обикновен браузър, не в приложението)." },
  rd_pt_sync_s3: { en: "Pickup Status → Sync from 賣貨便 → pick the file.", fil: "Pickup Status → Sync mula 賣貨便 → piliin ang file.", zh: "取件状态 → 从賣貨便同步 → 选择文件。", "zh-TW": "取件狀態 → 從賣貨便同步 → 選擇檔案。", vi: "Trạng thái lấy hàng → Đồng bộ từ 賣貨便 → chọn tệp.", th: "สถานะรับพัสดุ → ซิงค์จาก 賣貨便 → เลือกไฟล์", id: "Status Ambil → Sinkron dari 賣貨便 → pilih file.", bg: "Статус на получаване → Синхронизирай от 賣貨便 → избери файла." },
  rd_pt_sync_s4: { en: "Usernames appear right away under Waiting pickup; new parcels are checked automatically within a few minutes.", fil: "Lalabas agad ang usernames sa Hinihintay kunin; awtomatikong ichi-check ang mga bagong parcel sa loob ng ilang minuto.", zh: "帐号会立即出现在「待取货」中；新包裹会在几分钟内自动检查。", "zh-TW": "帳號會立即出現在「待取件」中；新包裹會在幾分鐘內自動檢查。", vi: "Username hiện ngay trong mục Chờ lấy hàng; bưu kiện mới được kiểm tra tự động trong vài phút.", th: "username จะแสดงทันทีในรายการ “รอรับ” พัสดุใหม่จะถูกตรวจอัตโนมัติภายในไม่กี่นาที", id: "Username langsung muncul di Menunggu diambil; paket baru dicek otomatis dalam beberapa menit.", bg: "Имената се появяват веднага в „Чакат получаване“; новите пратки се проверяват автоматично до няколко минути." },
  rd_pt_err_signed_out: { en: "Sign in again, then retry.", fil: "Mag-sign in ulit, tapos subukan muli.", zh: "请重新登录，然后再试一次。", "zh-TW": "請重新登入，然後再試一次。", vi: "Hãy đăng nhập lại rồi thử lại.", th: "กรุณาเข้าสู่ระบบอีกครั้ง แล้วลองใหม่", id: "Masuk lagi, lalu coba ulang.", bg: "Влезте отново и опитайте пак." },
