  // ── Messenger receipt step 1 (2026-10-05): receipt format + picture preview (FB preview accounts) ──
  rd_rc_title: { en: "Receipt format", fil: "Format ng resibo", zh: "收据格式", "zh-TW": "收據格式", vi: "Mẫu biên nhận", th: "รูปแบบใบเสร็จ", id: "Format struk", bg: "Формат на разписката" },
  rd_rc_sub: { en: "The Messenger receipt picture your Facebook buyers get after the live. Nothing is sent yet.", fil: "Ang larawan ng resibo sa Messenger na matatanggap ng Facebook buyers mo pagkatapos ng live. Wala pang ipinapadala.", zh: "直播结束后 Facebook 买家会收到的 Messenger 收据图片。目前尚不会发送。", "zh-TW": "直播結束後 Facebook 買家會收到的 Messenger 收據圖片。目前尚不會傳送。", vi: "Ảnh biên nhận Messenger mà người mua Facebook nhận sau buổi live. Hiện chưa gửi gì.", th: "รูปใบเสร็จ Messenger ที่ผู้ซื้อ Facebook จะได้รับหลังไลฟ์ ยังไม่มีการส่งในตอนนี้", id: "Gambar struk Messenger yang diterima pembeli Facebook setelah live. Belum ada yang dikirim.", bg: "Картинката-разписка в Messenger, която купувачите от Facebook получават след лайва. Засега нищо не се изпраща." },
  rd_rc_sub_live: { en: "The Messenger receipt picture your Facebook buyers get after the live.", fil: "Ang larawan ng resibo sa Messenger na matatanggap ng Facebook buyers mo pagkatapos ng live.", zh: "直播结束后 Facebook 买家会收到的 Messenger 收据图片。", "zh-TW": "直播結束後 Facebook 買家會收到的 Messenger 收據圖片。", vi: "Ảnh biên nhận Messenger mà người mua Facebook nhận sau buổi live.", th: "รูปใบเสร็จ Messenger ที่ผู้ซื้อ Facebook จะได้รับหลังไลฟ์", id: "Gambar struk Messenger yang diterima pembeli Facebook setelah live.", bg: "Картинката-разписка в Messenger, която купувачите от Facebook получават след лайва." },
  rd_rc_opening: { en: "Opening", fil: "Bati sa simula", zh: "开头", "zh-TW": "開頭", vi: "Lời mở đầu", th: "ข้อความเปิด", id: "Pembuka", bg: "Начало" },
  rd_rc_opening_ph: { en: "e.g. Thank you for joining our live!", fil: "hal. Salamat sa pagsali sa live namin!", zh: "例如：感谢您参加我们的直播！", "zh-TW": "例如：感謝您參加我們的直播！", vi: "vd. Cảm ơn bạn đã tham gia buổi live!", th: "เช่น ขอบคุณที่เข้าร่วมไลฟ์ของเรา!", id: "mis. Terima kasih sudah ikut live kami!", bg: "напр. Благодарим, че гледахте нашия лайв!" },
  rd_rc_note: { en: "Note — how to pay", fil: "Paalala — paano magbayad", zh: "备注 — 付款方式", "zh-TW": "備註 — 付款方式", vi: "Ghi chú — cách thanh toán", th: "หมายเหตุ — วิธีชำระเงิน", id: "Catatan — cara bayar", bg: "Бележка — как да платите" },
  rd_rc_note_ph: { en: "e.g. Please pay within 3 days and send a screenshot after paying.", fil: "hal. Pakibayaran sa loob ng 3 araw at mag-send ng screenshot pagkatapos.", zh: "例如：请于 3 天内付款，付款后发送截图。", "zh-TW": "例如：請於 3 天內付款，付款後傳送截圖。", vi: "vd. Vui lòng thanh toán trong 3 ngày và gửi ảnh chụp sau khi trả.", th: "เช่น กรุณาชำระภายใน 3 วัน และส่งภาพหน้าจอหลังชำระ", id: "mis. Mohon bayar dalam 3 hari dan kirim tangkapan layar setelah bayar.", bg: "напр. Моля, платете до 3 дни и изпратете снимка на плащането." },
  rd_rc_qr: { en: "Payment QR picture", fil: "Larawan ng payment QR", zh: "收款二维码图片", "zh-TW": "收款 QR 碼圖片", vi: "Ảnh mã QR thanh toán", th: "รูป QR สำหรับชำระเงิน", id: "Gambar QR pembayaran", bg: "Картинка с QR код за плащане" },
  rd_rc_qr_hint: { en: "Upload your own payment QR. It appears at the bottom of the receipt.", fil: "I-upload ang sarili mong payment QR. Lalabas ito sa ibaba ng resibo.", zh: "上传您自己的收款二维码，它会显示在收据底部。", "zh-TW": "上傳你自己的收款 QR 碼，它會顯示在收據底部。", vi: "Tải lên mã QR thanh toán của bạn. Mã sẽ hiện ở cuối biên nhận.", th: "อัปโหลด QR ชำระเงินของคุณเอง จะแสดงที่ด้านล่างของใบเสร็จ", id: "Unggah QR pembayaran Anda sendiri. QR muncul di bagian bawah struk.", bg: "Качете своя QR код за плащане. Той се показва в долната част на разписката." },
  rd_rc_qr_pick: { en: "Choose picture", fil: "Pumili ng larawan", zh: "选择图片", "zh-TW": "選擇圖片", vi: "Chọn ảnh", th: "เลือกรูป", id: "Pilih gambar", bg: "Изберете снимка" },
