  rd_rs_sending: { en: "Sending…", fil: "Ipinapadala…", zh: "正在发送…", "zh-TW": "正在傳送…", vi: "Đang gửi…", th: "กำลังส่ง…", id: "Mengirim…", bg: "Изпращане…" },
  rd_rs_sent_at: { en: "Sent ✓ {time}", fil: "Naipadala ✓ {time}", zh: "已发送 ✓ {time}", "zh-TW": "已傳送 ✓ {time}", vi: "Đã gửi ✓ {time}", th: "ส่งแล้ว ✓ {time}", id: "Terkirim ✓ {time}", bg: "Изпратено ✓ {time}" },
  rd_rs_none_left: { en: "Facebook allows one message per order comment, and this buyer's comments have all been used.", fil: "Isang message lang bawat order comment ang pinapayagan ng Facebook, at nagamit na lahat ng comment ng buyer na ito.", zh: "Facebook 每条下单留言只允许发送一则消息，该买家的留言都已用完。", "zh-TW": "Facebook 每則下單留言只允許傳送一則訊息，該買家的留言都已用完。", vi: "Facebook chỉ cho gửi một tin nhắn cho mỗi bình luận đặt hàng, và các bình luận của người mua này đã dùng hết.", th: "Facebook อนุญาตให้ส่งได้หนึ่งข้อความต่อหนึ่งคอมเมนต์สั่งซื้อ และคอมเมนต์ของผู้ซื้อรายนี้ถูกใช้หมดแล้ว", id: "Facebook hanya mengizinkan satu pesan per komentar pesanan, dan semua komentar pembeli ini sudah terpakai.", bg: "Facebook позволява едно съобщение на коментар-поръчка, а всички коментари на този купувач вече са използвани." },
  rd_rs_needs_messaging: { en: "To send receipts, authorize your Page again in Facebook channels.", fil: "Para makapagpadala ng resibo, i-authorize ulit ang Page mo sa Facebook channels.", zh: "如需发送收据，请在 Facebook 频道中重新授权您的粉丝专页。", "zh-TW": "如需傳送收據，請在 Facebook 頻道中重新授權你的粉專。", vi: "Để gửi biên nhận, hãy cấp quyền lại cho Trang trong mục kênh Facebook.", th: "หากต้องการส่งใบเสร็จ ให้อนุญาตเพจของคุณอีกครั้งในช่อง Facebook", id: "Untuk mengirim struk, otorisasi ulang Halaman Anda di saluran Facebook.", bg: "За да изпращате разписки, упълномощете страницата си отново във Facebook каналите." },
  rd_rs_unknown: { en: "We couldn't confirm the receipt was delivered. Check Messenger before sending again.", fil: "Hindi nakumpirma kung naipadala ang resibo. Tingnan muna sa Messenger bago magpadala ulit.", zh: "无法确认收据是否已送达。再次发送前请先查看 Messenger。", "zh-TW": "無法確認收據是否已送達。再次傳送前請先查看 Messenger。", vi: "Không xác nhận được biên nhận đã gửi tới chưa. Hãy kiểm tra Messenger trước khi gửi lại.", th: "ยืนยันไม่ได้ว่าใบเสร็จส่งถึงแล้วหรือไม่ ตรวจสอบใน Messenger ก่อนส่งอีกครั้ง", id: "Kami tidak bisa memastikan struk terkirim. Cek Messenger sebelum mengirim lagi.", bg: "Не можем да потвърдим, че разписката е доставена. Проверете Messenger, преди да изпратите пак." },
  rd_rs_no_private_reply: { en: "Facebook doesn't allow a private message to this commenter (they commented as a Page, or their settings block it).", fil: "Hindi pinapayagan ng Facebook ang private message sa nag-comment na ito (nag-comment siya bilang Page, o hinaharangan ito ng kanyang settings).", zh: "Facebook 不允许私信这位留言者（对方以粉丝专页身份留言，或其设置阻止了私信）。", "zh-TW": "Facebook 不允許私訊這位留言者（對方以粉專身分留言，或其設定封鎖了私訊）。", vi: "Facebook không cho phép nhắn riêng cho người bình luận này (họ bình luận bằng Trang, hoặc cài đặt của họ chặn tin nhắn).", th: "Facebook ไม่อนุญาตให้ส่งข้อความส่วนตัวถึงผู้คอมเมนต์นี้ (เขาคอมเมนต์ในนามเพจ หรือการตั้งค่าของเขาบล็อกไว้)", id: "Facebook tidak mengizinkan pesan pribadi ke pemberi komentar ini (mereka berkomentar sebagai Halaman, atau pengaturannya memblokir).", bg: "Facebook не позволява лично съобщение до този коментиращ (коментирал е като Страница или настройките му го блокират)." },
  rd_rs_failed: { en: "Couldn't send the receipt. Try again.", fil: "Hindi naipadala ang resibo. Subukan ulit.", zh: "收据发送失败，请重试。", "zh-TW": "收據傳送失敗，請重試。", vi: "Không gửi được biên nhận. Thử lại.", th: "ส่งใบเสร็จไม่สำเร็จ ลองอีกครั้ง", id: "Gagal mengirim struk. Coba lagi.", bg: "Разписката не се изпрати. Опитайте пак." },
  rd_fb_err_expired: { en: "Facebook access expired. Re-authorize this Page in Settings → Facebook.", fil: "Nag-expire ang access sa Facebook. I-connect ulit ang Page na ito sa Settings → Facebook.", zh: "Facebook 授权已过期。请在 设置 → Facebook 重新授权此主页。", "zh-TW": "Facebook 授權已過期。請到 設定 → Facebook 重新授權這個粉專。", vi: "Quyền Facebook đã hết hạn. Hãy cấp quyền lại Trang này trong Cài đặt → Facebook.", th: "สิทธิ์ Facebook หมดอายุแล้ว อนุญาตเพจนี้ใหม่ที่ ตั้งค่า → Facebook", id: "Akses Facebook kedaluwarsa. Otorisasi ulang Halaman ini di Pengaturan → Facebook.", bg: "Достъпът до Facebook изтече. Оторизирай страницата отново в Настройки → Facebook." },
