// Transpose RAW (key→langs) into REDESIGN_STRINGS (lang→keys).
export const REDESIGN_STRINGS: RedesignStrings = (() => {
  const out: RedesignStrings = { en: {}, fil: {}, zh: {}, "zh-TW": {}, vi: {}, th: {}, id: {}, bg: {} };
  for (const [key, row] of Object.entries(RAW)) {
    for (const lang of VALID_LANGS) out[lang][key] = row[lang];
  }
  return out;
})();

// Pure merge — supplement (new keys) wins over the production base. Exposed for tests.
export function applySupplement(base: Record<string, string>, supp: Record<string, string>): RedesignT {
  return { ...base, ...supp } as RedesignT;
}

export function buildT(lang: string, supplement: RedesignStrings = REDESIGN_STRINGS): RedesignT {
  const norm = normalizeLang(lang);
  // Build 10b: no production base any more — every key the redesign shows lives in RAW
  // (the old app's translations.ts no longer ships in this bundle).
  return applySupplement({}, supplement[norm] || {});
}

const TContext = createContext<RedesignT | null>(null);
export function TProvider({ lang, children }: { lang: string; children: ReactNode }) {
  const value = useMemo(() => buildT(lang), [lang]);
  // Normalized current language provided alongside T so language-agnostic DATA
  // (an auto-translated broadcast's message_i18n) renders per-seller, reactively.
  const norm = useMemo(() => normalizeLang(lang), [lang]);
  return (
    <LangContext.Provider value={norm}>
      <TContext.Provider value={value}>{children}</TContext.Provider>
    </LangContext.Provider>
  );
}
export function useT(): RedesignT {
  const ctx = useContext(TContext);
  if (!ctx) throw new Error("useT must be used within <TProvider>");
  return ctx;
}
